        try {
          const {
            data:
              sessionData,
            error:
              sessionError,
          } =
            await supabase
              .auth
              .getSession();

          if (
            sessionError
          ) {
            throw sessionError;
          }

          let user =
            sessionData
              .session
              ?.user ??
            null;

          if (
            !user
          ) {
            const {
              data:
                signInData,
              error:
                signInError,
            } =
              await supabase
                .auth
                .signInAnonymously();

            if (
              signInError
            ) {
              throw signInError;
            }

            user =
              signInData
                .user ??
              null;
          }

          if (
            !user
          ) {
            throw new Error(
              "Supabase user was not created."
            );
          }

          const [
            entitlementPremium,
            usage,
          ] =
            await Promise
              .all([
                loadEntitlement(
                  user.id
                ),

                loadDailyUsage(),
              ]);

          if (
            !active
          ) {
            return;
          }

          const premium =
            entitlementPremium ||
            usage
              .isPremium;

