const temporaryState=canonical.temporaryState?{...canonical.temporaryState,history:[...(Array.isArray(canonical.temporaryState.history)?canonical.temporaryState.history:[]),{role:"misaki",text:reply,sentAt:new Date().toISOString()}].slice(-60)}:null;
const temporaryToken=temporaryState?await sealTemporaryRoot(temporaryState,Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,canonical.temporaryExpiresAt!):null;
