export async function handler(req:Request){if(req.method!=="POST")return Response.json({error:"method_not_allowed"},{status:405});const secret=req.headers.get("x-cron-secret");if(!secret||secret.length!==64)return Response.json({error:"unauthorized_header",version:5},{status:401});const sk=Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");if(!sk||!SUPABASE_URL)return Response.json({error:"admin_config_missing"},{status:503});const s=createClient(SUPABASE_URL,sk,{auth:{persistSession:false,autoRefreshToken:false}}),{data:authorized,error:ae}=await s.rpc("verify_misaki_body_clock_secret",{p_secret:secret});if(ae)return Response.json({error:"auth_unavailable"},{status:503});if(authorized!==true)return Response.json({error:"unauthorized_secret",version:5},{status:401});const key=Deno.env.get("GEMINI_API_KEY");let relayReady=false,relayError:string|null=null;try{relayReady=(await relayPush("health")).ok===true}catch(e){relayError=e instanceof Error?e.message:"relay_unavailable"}const ready={gemini:!!key,pushRelay:relayReady};if(new URL(req.url).searchParams.get("mode")==="health")return Response.json({ok:Object.values(ready).every(Boolean),ready,relayError,version:"body-clock-grounded-life-v4"});if(!Object.values(ready).every(Boolean))return Response.json({error:"configuration_not_ready",ready,relayError},{status:503});const limit=Math.max(1,Math.min(MAX_PER_RUN,Number(new URL(req.url).searchParams.get("limit"))||MAX_PER_RUN)),{data,error}=await s.rpc("claim_misaki_body_clock_due_users",{p_limit:limit});if(error)return Response.json({error:"claim_failed"},{status:500});const rows=(data||[])as BodyClockRow[],results:any[]=[];let cursor=0;const worker=async()=>{while(cursor<rows.length){const row=rows[cursor++];try{const r=await processUser(s,key!,row);results.push({ok:!("failed"in r.push)||r.push.failed===0,...r})}catch(e){console.error("BODY_CLOCK_USER_FAILED",row.user_id);results.push({ok:false,userId:row.user_id,error:e instanceof Error?e.message:"delivery_failed"})}}};await P